let quickRows=[],quickFocus=null,quickWorker=null,quickRevision=0,quickTimer;
const quickPanel=document.createElement('section');quickPanel.id='quickPanel';$('viewTabs')?.after(quickPanel);
document.querySelector('.viewTabs').after(quickPanel);
quickPanel.innerHTML=`<h2>Pick your heroes. We handle the rest.</h2><p>Choose a hero by role, or use a suggestion. Record any ban; your picks stay fixed and replacements update automatically.</p><p class="note">No opponent setup needed: recommendations assume varied hypothetical opponents, both sides, and DotaCaptain’s default item presets. Fast suggestions use native draft scores. Ban candidates protect your picks, without predicting enemy roles. Completed teams optimize automatically; simulation can take several minutes.</p><div id="quickRoles" class="quickRoles"></div><div class="quickBanBar"><label>Record a banned hero<select id="quickBan" aria-label="Record a banned hero"></select></label><button id="quickReset">Clear picks & bans</button></div><div id="quickBans" class="chips"></div><p id="quickStatus" role="status" aria-live="polite"></p><section id="quickResult"></section>`;
$('quickRoles').innerHTML=L.roles.map(role=>`<article><h3>${L.names[role]}</h3><label>Choose ${L.names[role].split(' · ')[0]}<select data-quick-role="${role}" aria-label="Quick ${role}"><option value="">Choose hero…</option>${D.heroes.filter(h=>L.valid(h,role)).map(h=>`<option value="${h.id}">${escape(h.localized_name)}</option>`).join('')}</select></label><div data-quick-suggestions="${role}"></div></article>`).join('');
$('quickBan').innerHTML=options(null,'Choose banned hero…');
const previousSetView=setView;
setView=function(view){previousSetView(view);$('quickTab').setAttribute('aria-pressed',view==='quick');if(view==='quick')refreshQuick()};
$('quickTab').onclick=()=>setView('quick');
function quickAvailable(){const own=locks(),used=new Set([...Object.values(own),...enemy(),...bans]);for(const s of document.querySelectorAll('[data-quick-role]')){s.value=own[s.dataset.quickRole]||'';for(const o of s.options)o.disabled=!!o.value&&+o.value!==+s.value&&used.has(+o.value)}for(const o of $('quickBan').options)o.disabled=!!o.value&&used.has(+o.value);$('quickBans').innerHTML=bans.map(id=>`<button data-quick-remove="${id}">Unban ${escape(hero(id).localized_name)} ×</button>`).join('')}
function stopQuick(){clearTimeout(quickTimer);quickRevision++;quickWorker?.terminate();quickWorker=null}
function quickJob(action,args,onResult){const revision=quickRevision;quickWorker=new Worker('worker.js?v=quick1');quickWorker.onmessage=({data})=>{if(revision!==quickRevision)return;if(data.progress){$('quickStatus').textContent=data.progress;return}quickWorker.terminate();quickWorker=null;if(data.error){$('quickStatus').textContent=data.error;return}onResult(data.result)};quickWorker.onerror=()=>{$('quickStatus').textContent='Could not calculate suggestions. Change a pick to try again.';quickWorker?.terminate();quickWorker=null};quickWorker.postMessage({action,args})}
function showQuick(team){
 quickFocus=team;const complete=Object.keys(locks()).length===5;
 $('quickResult').innerHTML=`<h3>${complete?'Your completed team':'Suggested team preview'}</h3><div class="quickLineup">${team.ids.map((id,i)=>`<div><small>${L.names[L.roles[i]]}</small><strong>${escape(hero(id).localized_name)}</strong>${locks()[L.roles[i]]?'Picked':`<button data-quick-pick="${id}" data-role="${L.roles[i]}">Pick ${escape(hero(id).localized_name)}</button>`}</div>`).join('')}</div><h3>${team.generalOptimization?'Simulation-selected configuration':team.overall?'Previously tested configuration':'Best native-score configuration · 64 plans checked'}</h3><p>${escape(planName(team.choices))}</p><p class="note">${team.overall?`${team.overall.wins}/${team.overall.total} hypothetical scenario wins. These are not live-match odds.`:`Native draft value ${team.score.toFixed(1)}. This configuration has not been simulation-tested.`}</p>${complete?'<button id="quickCancel">Stop optimization</button>':''}<details><summary>Default item presets</summary>${team.ids.map((id,i)=>`<p><b>${escape(hero(id).localized_name)}</b> (${L.names[L.roles[i]]}): ${L.defaultBuilds(team.ids)[id].map(item=>escape(D.items.find(x=>x.id===item)?.name||item)).join(' → ')}</p>`).join('')}</details>`;
 if($('quickCancel'))$('quickCancel').hidden=!quickWorker;
}
function quickSuggestions(){
 const own=locks(),used=new Set([...Object.values(own),...bans,...enemy()]);
 // Native ban values protect the confirmed picks and displayed plan; enemy roles are unknown.
 const plan=quickFocus?.choices||D.presets.teamfightRosh,banRows=L.draftAdvice({locks:own,bans,ownBans,enemy:enemy(),choices:plan,action:'ban'}).rows;
 for(const role of L.roles){const el=document.querySelector(`[data-quick-suggestions="${role}"]`);if(own[role]){const banOptions=banRows.filter(x=>L.valid(hero(x.id),role)&&!used.has(x.id)).slice(0,3);el.innerHTML='<p class="note">Picked · change the selector to replace.</p>'+ (banOptions.length?'<h4>Ban candidates</h4>':'')+banOptions.map(x=>'<button class="quickBanSuggestion" data-quick-ban="'+x.id+'">Ban '+escape(hero(x.id).localized_name)+'</button>').join('');continue}const slot=L.roles.indexOf(role),picked=[];
  for(const t of quickRows)if(!picked.includes(t.ids[slot])&&!used.has(t.ids[slot]))picked.push(t.ids[slot]);
  // Complete the role-specific shortlist against the preview, retaining its other heroes.
  if(quickFocus&&picked.length<3){const rest=quickFocus.ids.filter((_,i)=>i!==slot);const ranked=D.heroes.filter(h=>!used.has(h.id)&&!rest.includes(h.id)&&L.valid(h,role)).map(h=>{const ids=[...quickFocus.ids];ids[slot]=h.id;return{id:h.id,score:L.score(ids,plan,enemy()).score}}).sort((a,b)=>b.score-a.score);for(const x of ranked)if(!picked.includes(x.id))picked.push(x.id)}
  const banOptions=banRows.filter(x=>L.valid(hero(x.id),role)&&!used.has(x.id)).slice(0,3);
  el.innerHTML=`<h4>Pick suggestions</h4>${picked.slice(0,3).map(id=>`<button data-quick-pick="${id}" data-role="${role}">${escape(hero(id).localized_name)}</button>`).join('')}<h4>Ban candidates</h4>${banOptions.map(x=>`<button class="quickBanSuggestion" data-quick-ban="${x.id}">Ban ${escape(hero(x.id).localized_name)}</button>`).join('')}`;
 }
}
function applyQuickRows(rows){quickRows=rows;if(!rows.length){$('quickResult').textContent='No compatible team found. Remove a constraint and try again.';return}showQuick(rows[0]);quickSuggestions();$('quickStatus').textContent=rows[0].overall?'Showing compatible teams from the tested reference.':'Suggestions updated · native-score search, not simulated wins.';
 const complete=Object.keys(locks()).length===5;if(complete){$('quickStatus').textContent='Configuration ready. Automatically checking stronger configurations in the simulator…';quickJob('generalOptimize',{teams:[rows[0]],context:{bans:[...bans],profiles:128}},result=>{showQuick(result[0]);$('quickStatus').textContent='Optimization complete · 64 plans screened, shortlist refined, chosen plan evaluated separately. A global optimum is not proven.'});$('quickCancel').hidden=false}
}
function refreshQuick(){stopQuick();quickAvailable();$('quickResult').innerHTML='';document.querySelectorAll('[data-quick-suggestions]').forEach(e=>e.innerHTML='<p class="note">Updating…</p>');const own=locks(),reference=generalBaseline?.teams||[],compatible=reference.filter(t=>L.roles.every((r,i)=>!own[r]||own[r]===t.ids[i])&&!t.ids.some(id=>bans.includes(id)||enemy().includes(id))).sort(L.overallSort);
 if(compatible.length){applyQuickRows(compatible.slice(0,6).map(t=>bans.length||enemy().length?L.bestPlan(t.ids,enemy()):t));return}
 $('quickStatus').textContent='Finding compatible replacements…';const focus=quickFocus;quickTimer=setTimeout(()=>quickJob('quick',{locks:own,bans:[...bans],enemy:enemy(),reference:reference.map(t=>({ids:t.ids,choices:t.choices})),focus},applyQuickRows),120);
}
function quickChange(){markChanged();updateKnowledge();refreshQuick()}
$('quickRoles').onchange=e=>{if(!e.target.dataset.quickRole)return;document.querySelector(`#locks [data-role="${e.target.dataset.quickRole}"]`).value=e.target.value;quickChange()};
$('quickBan').onchange=e=>{if(e.target.value){bans.push(+e.target.value);e.target.value='';renderBans();quickChange()}};
quickPanel.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.quickPick){document.querySelector(`#locks [data-role="${b.dataset.role}"]`).value=b.dataset.quickPick;quickChange()}else if(b.dataset.quickBan){bans.push(+b.dataset.quickBan);ownBans.push(+b.dataset.quickBan);renderBans();quickChange()}else if(b.dataset.quickRemove){const id=+b.dataset.quickRemove;bans=bans.filter(x=>x!==id);ownBans=ownBans.filter(x=>x!==id);renderBans();quickChange()}else if(b.id==='quickReset'){document.querySelectorAll('#locks select,#enemy select').forEach(s=>s.value='');bans=[];ownBans=[];quickFocus=null;renderBans();quickChange()}else if(b.id==='quickCancel'){stopQuick();b.hidden=true;$('quickStatus').textContent='Optimization stopped. Displayed configuration is retained.'}};
// Stop background work when leaving the quick board; advanced workflows remain available.
for(const id of ['draftTab','teamsTab'])$(id).addEventListener('click',stopQuick);
setView('quick');
